                            e.preventDefault();
                            onSend();
                        }
                    }}
                />
                <Tooltip title={disabled ? 'Connecting' : 'Send message'}>
                    <span>
                        <IconButton
                            type="submit"
                            size="small"
                            className="chat-send-button"
                            disabled={disabled || !value.trim()}
                        >
                            <SendRoundedIcon fontSize="small" />
                        </IconButton>
                    </span>
                </Tooltip>
            </div>
        </form>
    );
}

